<?php $sortUrl=static function(string $key):string{$query=$_GET;$query['sort']=$key;$query['direction']=isset($_GET['sort'])&&$_GET['sort']===$key&&strtolower((string)($_GET['direction']??'desc'))==='asc'?'desc':'asc';$query['page']=1;return admin_url('accounts?'.http_build_query($query));}; ?>
<div class="admin-table-scroll"><table class="admin-table admin-data-table"><thead><tr><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('number')) ?>" data-list-page>Account Number</a></th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('owner')) ?>" data-list-page>Owner</a></th><th scope="col">Type / Currency</th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('balance')) ?>" data-list-page>Virtual Balance</a></th><th scope="col">Open Positions</th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('status')) ?>" data-list-page>Status</a></th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('created')) ?>" data-list-page>Created</a></th><th scope="col"><span class="sr-only">Action</span></th></tr></thead><tbody>
<?php if(!empty($accounts)): foreach($accounts as $account): ?><tr><td data-label="Account Number"><a class="admin-row-link" href="<?= e(admin_url('accounts/'.$account['account_number'])) ?>"><?= e($account['account_number']) ?></a></td><td data-label="Owner"><div class="admin-user-cell"><strong><?= e(trim($account['first_name'].' '.$account['last_name'])) ?></strong><small><?= e($account['email']) ?> · <?= e($account['user_reference']) ?></small></div></td><td data-label="Type / Currency"><?= e(ucwords(str_replace('_',' ',$account['account_type']))) ?><small class="admin-cell-subtext"><?= e($account['currency']) ?> · DEMO</small></td><td data-label="Virtual Balance"><?= e(App\Services\DashboardService::formatMoney((string)$account['balance'],(string)$account['currency'])) ?></td><td data-label="Open Positions"><?= (int)$account['open_positions'] ?></td><td data-label="Status"><span class="admin-status-badge status-<?= e($account['status']) ?>"><?= e(ucwords($account['status'])) ?></span></td><td data-label="Created"><?= e(App\Services\DashboardService::formatDate($account['created_at'])) ?></td><td data-label="Action"><a class="admin-row-link" href="<?= e(admin_url('accounts/'.$account['account_number'])) ?>">View account</a></td></tr><?php endforeach; else: ?><tr><td class="admin-table-empty" colspan="8"><strong>No Demo Accounts match these filters.</strong><span>Adjust the search or filters and try again.</span></td></tr><?php endif; ?></tbody></table></div>
